using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;
public static class ActivityEndpoints {
 public static void Map(RouteGroupBuilder api){
 var t=api.MapGroup("/societies/{tenant:guid}/community").RequireAuthorization().RequireRateLimiting("community");
 t.MapDelete("/posts/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a)=>{await a.Member(tenant);var p=await db.Set<ActivityPost>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id)??throw new AccessDeniedException();if(p.AuthorId!=a.UserId)await a.Require(tenant,"activities.moderate",p.UnitId);p.Status="Archived";p.Revision++;a.Audit(tenant,"activity.archived",id);await db.SaveChangesAsync();return Results.NoContent();});
 t.MapGet("/authors",async(Guid tenant,AppDb db,Access a,CommunityService s)=>{await a.Member(tenant);return await (from p in s.Posts(tenant).Where(p=>p.Status=="Published") join u in db.Users on p.AuthorId equals u.Id select new{u.Id,name=u.FullName}).Distinct().OrderBy(u=>u.name).Take(200).ToListAsync();});
 t.MapGet("/setup",async(Guid tenant,AppDb db,Access a,CommunityService s)=>{await a.Member(tenant);var own=s.Mine(tenant).Select(m=>m.ChapterId);var units=a.Visible(tenant,"activities.read").Select(u=>u.Id);return Results.Ok(new{policy=await s.Policy(tenant),categories=await db.Set<ActivityCategory>().Where(c=>c.TenantId==tenant).OrderBy(c=>c.Name).ToListAsync(),organizations=await db.Units.Where(u=>u.TenantId==tenant&&(own.Contains(u.Id)||units.Contains(u.Id))).OrderBy(u=>u.Name).Take(500).Select(u=>new{u.Id,u.Name,u.ParentId,u.LevelId}).ToListAsync(),mine=await s.Mine(tenant).Select(m=>new{m.Id,m.ChapterId}).ToListAsync()});});
 t.MapPut("/policy",async(Guid tenant,CommunityPolicy r,AppDb db,Access a)=>{await a.Require(tenant,"activities.settings");CommunityService.Stages(r.PostStages);CommunityService.Stages(r.EventStages);var p=await db.Set<CommunityPolicy>().SingleAsync(x=>x.TenantId==tenant);if(p.Revision!=r.Revision)return Results.Conflict();p.MemberPosting=r.MemberPosting;p.PublicAllowed=r.PublicAllowed;p.BlockingAllowed=r.BlockingAllowed;p.PostStages=r.PostStages;p.EventStages=r.EventStages;p.Revision++;a.Audit(tenant,"community.policy.updated",p.Id);await db.SaveChangesAsync();return Results.NoContent();});
 t.MapPost("/categories",async(Guid tenant,MemberCategoryRequest r,string? kind,AppDb db,Access a)=>{await a.Require(tenant,"activities.settings");if(kind!=null&&kind!="Activity"&&kind!="Event")throw new DomainException("Invalid category kind");var c=new ActivityCategory{TenantId=tenant,Name=r.Name,Kind=kind??"Activity",Active=r.Active};db.Add(c);a.Audit(tenant,"activity.category.created",c.Id);await db.SaveChangesAsync();return Results.Ok(c);});
 t.MapPut("/categories/{id:guid}",async(Guid tenant,Guid id,MemberCategoryRequest r,AppDb db,Access a)=>{await a.Require(tenant,"activities.settings");var c=await db.Set<ActivityCategory>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();c.Name=r.Name;c.Active=r.Active;a.Audit(tenant,"activity.category.updated",id);await db.SaveChangesAsync();return Results.NoContent();});
 t.MapGet("/feed",async(Guid tenant,Guid? workspace,Guid? chapter,Guid? category,Guid? author,Guid? relatedEvent,string? status,string? search,DateTimeOffset? from,DateTimeOffset? to,DateTimeOffset? before,Guid? beforeId,bool? bookmarks,AppDb db,Access a,CommunityService s)=>{
 await a.Member(tenant);var q=s.Posts(tenant);if(status==null)q=q.Where(p=>p.Status=="Published");else q=q.Where(p=>p.Status==status);var branch=a.InWorkspace(db.Units.Where(u=>u.TenantId==tenant),tenant,workspace).Select(u=>u.Id);if(workspace!=null)q=q.Where(p=>p.UnitId!=null&&branch.Contains(p.UnitId.Value));if(chapter!=null)q=q.Where(p=>p.UnitId==chapter);if(category!=null)q=q.Where(p=>p.CategoryId==category);if(author!=null)q=q.Where(p=>p.AuthorId==author);if(relatedEvent!=null)q=q.Where(p=>p.EventId==relatedEvent);if(from!=null)q=q.Where(p=>(p.PublishedAt??p.CreatedAt)>=from);if(to!=null)q=q.Where(p=>(p.PublishedAt??p.CreatedAt)<to);if(!string.IsNullOrWhiteSpace(search))q=q.Where(p=>p.Title.Contains(search)||p.Body.Contains(search));if(bookmarks==true)q=q.Where(p=>db.Set<ActivityBookmark>().Any(b=>b.TenantId==tenant&&b.PostId==p.Id&&b.UserId==a.UserId));if(before!=null)q=q.Where(p=>(p.PublishedAt??p.CreatedAt)<before||((p.PublishedAt??p.CreatedAt)==before&&p.Id.CompareTo(beforeId??Guid.Empty)<0));
 var rows=await q.OrderByDescending(p=>p.PublishedAt??p.CreatedAt).ThenByDescending(p=>p.Id).Take(21).Select(p=>new{p.Id,p.Title,p.Body,p.UnitId,p.Official,p.CommitteeId,p.AuthorId,author=db.Users.Where(u=>u.Id==p.AuthorId).Select(u=>u.FullName).First(),organization=db.Units.Where(u=>u.Id==p.UnitId).Select(u=>u.Name).FirstOrDefault()??"Society headquarters",category=db.Set<ActivityCategory>().Where(c=>c.Id==p.CategoryId).Select(c=>c.Name).First(),p.CategoryId,p.Status,p.Revision,p.PublishedAt,p.CreatedAt,p.Featured,p.Achievement,p.Visibility,p.Tags,p.Location,p.EventId,reactions=db.Set<ActivityReaction>().Count(r=>r.TenantId==tenant&&r.PostId==p.Id),comments=db.Set<ActivityComment>().Count(c=>c.TenantId==tenant&&c.PostId==p.Id&&!c.Hidden),mine=db.Set<ActivityReaction>().Where(r=>r.TenantId==tenant&&r.PostId==p.Id&&r.UserId==a.UserId).Select(r=>r.Kind).FirstOrDefault(),bookmarked=db.Set<ActivityBookmark>().Any(b=>b.TenantId==tenant&&b.PostId==p.Id&&b.UserId==a.UserId),media=db.Set<CommunityMedia>().Where(m=>m.TenantId==tenant&&m.ResourceId==p.Id&&m.ResourceKind=="Post").OrderByDescending(m=>m.Cover).ThenBy(m=>m.Sort).Select(m=>new{m.Id,m.Name,m.ContentType}).ToArray()}).ToListAsync();return Results.Ok(new{items=rows.Take(20),hasMore=rows.Count>20,next=rows.Count>20?new{before=rows[19].PublishedAt??rows[19].CreatedAt,beforeId=rows[19].Id}:null});});
 t.MapGet("/posts/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s)=>{var p=await s.Post(tenant,id);var manage=p.AuthorId==a.UserId||await a.Can(tenant,"activities.moderate",p.UnitId);return Results.Ok(new{post=p,canEdit=p.AuthorId==a.UserId&&p.Status!="Removed",canReview=await a.Can(tenant,"activities.approve",p.UnitId)&&p.AuthorId!=a.UserId,canModerate=await a.Can(tenant,"activities.moderate",p.UnitId),comments=await db.Set<ActivityComment>().Where(c=>c.TenantId==tenant&&c.PostId==id&&!c.Hidden).OrderBy(c=>c.At).Take(100).Select(c=>new{c.Id,c.Body,c.ParentId,c.At,c.UserId,name=db.Users.Where(u=>u.Id==c.UserId).Select(u=>u.FullName).First()}).ToListAsync(),media=await db.Set<CommunityMedia>().Where(m=>m.TenantId==tenant&&m.ResourceId==id&&m.ResourceKind=="Post").OrderBy(m=>m.Sort).ToListAsync()});});
 t.MapPost("/posts",async(Guid tenant,PostWrite r,AppDb db,Access a,CommunityService s)=>{var p=new ActivityPost{TenantId=tenant,AuthorId=a.UserId};await Apply(p,r,db,a,s);db.Add(p);s.Version(tenant,p.Id,"Post",0,p);await db.SaveChangesAsync();return Results.Ok(p);});
 t.MapPut("/posts/{id:guid}",async(Guid tenant,Guid id,PostWrite r,AppDb db,Access a,CommunityService s)=>{var p=await db.Set<ActivityPost>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id)??throw new AccessDeniedException();if(p.AuthorId!=a.UserId)throw new AccessDeniedException();if(p.Revision!=r.Revision)return Results.Conflict();if(p.Status=="Removed")throw new DomainException("Removed content cannot be republished");await Apply(p,r,db,a,s);p.Revision++;s.Version(tenant,id,"Post",p.Revision,p);await db.SaveChangesAsync();return Results.Ok(p);});
 t.MapPost("/posts/{id:guid}/decision",async(Guid tenant,Guid id,CommunityReview r,AppDb db,Access a,CommunityService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var p=await db.Set<ActivityPost>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id)??throw new AccessDeniedException();if(p.Revision!=r.Revision)return Results.Conflict();if(p.Status!="Pending Approval")throw new DomainException("Post is not awaiting review");await s.Decision(tenant,id,p.AuthorId,p.UnitId,"Post",p.Stages,p.Stage,r);if(r.Decision=="Approve"){p.Stage++;if(p.Stage==CommunityService.Stages(p.Stages).Length){p.Status=CommunityService.Ready(p.ScheduledAt);if(p.Status=="Published")p.PublishedAt=DateTimeOffset.UtcNow;}}else p.Status=r.Decision=="Reject"?"Rejected":"Changes Requested";p.Revision++;await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(p);});
 t.MapGet("/posts/{id:guid}/history",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s)=>{var p=await s.Post(tenant,id);if(p.AuthorId!=a.UserId)await a.Require(tenant,"activities.approve",p.UnitId);return Results.Ok(new{versions=await db.Set<CommunityVersion>().Where(v=>v.TenantId==tenant&&v.ResourceId==id&&v.Kind=="Post").OrderByDescending(v=>v.At).Take(100).ToListAsync(),decisions=await db.Set<CommunityDecision>().Where(v=>v.TenantId==tenant&&v.ResourceId==id&&v.Kind=="Post").OrderBy(v=>v.At).Take(100).ToListAsync()});});
 t.MapPut("/posts/{id:guid}/reaction",async(Guid tenant,Guid id,ReactionWrite r,AppDb db,Access a,CommunityService s)=>{var p=await s.Post(tenant,id);if(p.Status!="Published")throw new DomainException("Post is not published");if(!new[]{"Like","Appreciate","Celebrate","Support",""}.Contains(r.Kind))throw new DomainException("Unknown reaction");await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO \"ActivityReaction\" (\"Id\",\"TenantId\",\"PostId\",\"UserId\",\"Kind\") VALUES ({Guid.NewGuid()},{tenant},{id},{a.UserId},{r.Kind}) ON CONFLICT (\"TenantId\",\"PostId\",\"UserId\") DO UPDATE SET \"Kind\"=EXCLUDED.\"Kind\"");if(r.Kind=="")await db.Set<ActivityReaction>().Where(x=>x.TenantId==tenant&&x.PostId==id&&x.UserId==a.UserId).ExecuteDeleteAsync();return Results.NoContent();});
 t.MapPost("/posts/{id:guid}/comments",async(Guid tenant,Guid id,CommentWrite r,AppDb db,Access a,CommunityService s)=>{var p=await s.Post(tenant,id);if(p.Status!="Published")throw new DomainException("Post is not published");if(r.ParentId!=null&&!await db.Set<ActivityComment>().AnyAsync(c=>c.TenantId==tenant&&c.PostId==id&&c.Id==r.ParentId&&!c.Hidden))throw new DomainException("Reply parent not available");var mentions=(r.Mentions??[]).Distinct().ToArray();if(mentions.Length>20||await s.Mine(tenant).CountAsync()==0&&!await a.Can(tenant,"activities.read",p.UnitId))throw new AccessDeniedException();var c=new ActivityComment{TenantId=tenant,PostId=id,UserId=a.UserId,ParentId=r.ParentId,Body=CommunityService.Rich(r.Body)};db.Add(c);a.Audit(tenant,"activity.comment.created",c.Id,new{post=id,mentions});await db.SaveChangesAsync();return Results.Ok(c);});
 t.MapPut("/posts/{id:guid}/bookmark",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s)=>{await s.Post(tenant,id);await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO \"ActivityBookmark\" (\"Id\",\"TenantId\",\"PostId\",\"UserId\") VALUES ({Guid.NewGuid()},{tenant},{id},{a.UserId}) ON CONFLICT (\"TenantId\",\"PostId\",\"UserId\") DO NOTHING");return Results.NoContent();});
 t.MapDelete("/posts/{id:guid}/bookmark",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s)=>{await s.Post(tenant,id);await db.Set<ActivityBookmark>().Where(b=>b.TenantId==tenant&&b.PostId==id&&b.UserId==a.UserId).ExecuteDeleteAsync();return Results.NoContent();});
 t.MapPost("/posts/{id:guid}/report",async(Guid tenant,Guid id,ReportWrite r,AppDb db,Access a,CommunityService s)=>{await s.Post(tenant,id);if(!await db.Set<ActivityReport>().AnyAsync(x=>x.TenantId==tenant&&x.PostId==id&&x.UserId==a.UserId))db.Add(new ActivityReport{TenantId=tenant,PostId=id,UserId=a.UserId,Reason=r.Reason});a.Audit(tenant,"activity.reported",id);await db.SaveChangesAsync();return Results.NoContent();});
 t.MapGet("/reports",async(Guid tenant,AppDb db,Access a)=>{await a.Member(tenant);var units=a.Visible(tenant,"activities.moderate").Select(u=>u.Id);var all=await a.Can(tenant,"activities.moderate");return await db.Set<ActivityReport>().Where(r=>r.TenantId==tenant&&db.Set<ActivityPost>().Any(p=>p.Id==r.PostId&&(all||p.UnitId!=null&&units.Contains(p.UnitId.Value)))).OrderByDescending(r=>r.At).Take(100).ToListAsync();});
 t.MapPost("/posts/{id:guid}/moderate",async(Guid tenant,Guid id,CommunityReview r,AppDb db,Access a)=>{var p=await db.Set<ActivityPost>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"activities.moderate",p.UnitId);if(p.Revision!=r.Revision)return Results.Conflict();if(!new[]{"Archived","Removed","Feature","Unfeature"}.Contains(r.Decision)||string.IsNullOrWhiteSpace(r.Note))throw new DomainException("Supply a moderation action and reason");if(r.Decision=="Feature")p.Featured=true;else if(r.Decision=="Unfeature")p.Featured=false;else p.Status=r.Decision;p.Revision++;foreach(var report in await db.Set<ActivityReport>().Where(x=>x.TenantId==tenant&&x.PostId==id&&x.Status=="Open").ToListAsync())report.Status="Resolved";a.Audit(tenant,"activity.moderated",id,new{r.Decision,r.Note});await db.SaveChangesAsync();return Results.NoContent();});
 t.MapPost("/comments/{id:guid}/hide",async(Guid tenant,Guid id,ReportWrite r,AppDb db,Access a)=>{var c=await db.Set<ActivityComment>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();var p=await db.Set<ActivityPost>().SingleAsync(p=>p.Id==c.PostId&&p.TenantId==tenant);if(c.UserId!=a.UserId)await a.Require(tenant,"activities.moderate",p.UnitId);c.Hidden=true;a.Audit(tenant,"activity.comment.hidden",id,new{r.Reason});await db.SaveChangesAsync();return Results.NoContent();});
 t.MapPut("/blocks/{user:guid}",async(Guid tenant,Guid user,AppDb db,Access a,CommunityService s)=>{await a.Member(tenant);if(!(await s.Policy(tenant)).BlockingAllowed||user==a.UserId||!await db.Links.AnyAsync(l=>l.TenantId==tenant&&l.UserId==user))throw new AccessDeniedException();if(!await db.Set<CommunityBlock>().AnyAsync(b=>b.TenantId==tenant&&b.UserId==a.UserId&&b.BlockedUserId==user))db.Add(new CommunityBlock{TenantId=tenant,UserId=a.UserId,BlockedUserId=user});await db.SaveChangesAsync();return Results.NoContent();});
 t.MapDelete("/blocks/{user:guid}",async(Guid tenant,Guid user,AppDb db,Access a)=>{await a.Member(tenant);await db.Set<CommunityBlock>().Where(b=>b.TenantId==tenant&&b.UserId==a.UserId&&b.BlockedUserId==user).ExecuteDeleteAsync();return Results.NoContent();});
 }
 internal static async Task Apply(ActivityPost p,PostWrite r,AppDb db,Access a,CommunityService s){var audience=await s.Audience(p.TenantId,r.UnitId,r.Visibility,r.Audience,r.Official);if(r.Title.Length>180||r.Location.Length>500||(r.Tags??[]).Length>20||(r.Tags??[]).Any(t=>t.Length>50)||string.IsNullOrWhiteSpace(r.Body))throw new DomainException("Check title, tags and content");if(!await db.Set<ActivityCategory>().AnyAsync(c=>c.Id==r.CategoryId&&c.TenantId==p.TenantId&&c.Active&&c.Kind=="Activity"))throw new DomainException("Choose an active activity category");if(r.CommitteeId!=null){var c=await db.Committees.SingleOrDefaultAsync(c=>c.Id==r.CommitteeId&&c.TenantId==p.TenantId&&c.Status=="Active")??throw new AccessDeniedException();if(!r.Official||c.UnitId!=r.UnitId)throw new AccessDeniedException();await a.Require(p.TenantId,"activities.official",c.UnitId);}if(r.EventId!=null){var e=await s.Event(p.TenantId,r.EventId.Value);if(e.Status!="Published")throw new DomainException("Related event must be published");}if(r.Achievement&&!r.Official)throw new AccessDeniedException();var mentions=(r.Mentions??[]).Distinct().ToArray();var directory=(await new MembershipService(db,a).Directory(p.TenantId)).Select(m=>m.Id);if(mentions.Length>20||await directory.CountAsync(m=>mentions.Contains(m))!=mentions.Length)throw new AccessDeniedException();
 p.UnitId=r.UnitId;p.Official=r.Official;p.CommitteeId=r.CommitteeId;p.CategoryId=r.CategoryId;p.Title=r.Title;p.Body=CommunityService.Rich(r.Body);p.Location=r.Location;p.Visibility=r.Visibility;p.Audience=audience;p.EventId=r.EventId;p.Tags=r.Tags??[];p.Mentions=mentions;p.ScheduledAt=r.ScheduledAt?.ToUniversalTime();p.Achievement=r.Achievement;p.Stages=(await s.Policy(p.TenantId)).PostStages;p.Stage=0;p.Status=r.Submit?(CommunityService.Stages(p.Stages).Length==0?CommunityService.Ready(p.ScheduledAt):"Pending Approval"):"Draft";p.PublishedAt=p.Status=="Published"?DateTimeOffset.UtcNow:null;
 }
}
